<?php declare(strict_types=1); ?><div class="mb-5"><a class="text-sm font-semibold text-navy-700" href="<?= e(admin_url('pages')) ?>">← Back to pages</a></div><form method="post" action="<?= e(admin_url('pages/'.$page['id'])) ?>" class="space-y-6"><?= csrf_field() ?><section class="card p-6"><h2 class="t-h3 text-[1.0625rem]">Search and sharing</h2><div class="mt-5 grid gap-5"><div><label class="field-label">Browser title</label><input class="field" name="title" maxlength="190" value="<?= e($page['title']??'') ?>"></div><div><label class="field-label">Meta description</label><textarea class="field h-auto py-3" name="meta_description" maxlength="255" rows="3"><?= e($page['meta_description']??'') ?></textarea></div><div><label class="field-label">Social image</label><select class="field" name="og_image_id"><option value="0">None</option><?php foreach($media as $image): ?><option value="<?= $image['id'] ?>" <?= (int)$page['og_image_id']===(int)$image['id']?'selected':'' ?>><?= e($image['alt'].' — '.$image['path']) ?></option><?php endforeach; ?></select></div></div></section><?php foreach($sections as $section): ?><section class="card p-6"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="font-sans text-base font-semibold text-navy-700"><?= e($section['name']) ?></h2><p class="t-meta text-muted"><?= e($section['section_key']) ?></p></div><div class="flex items-center gap-4"><label class="text-sm"><input type="checkbox" name="section_enabled[<?= $section['id'] ?>]" <?= $section['enabled']?'checked':'' ?>> Enabled</label><label class="text-sm">Order <input class="field ml-2 w-20" type="number" name="section_sort[<?= $section['id'] ?>]" value="<?= (int)$section['sort'] ?>"></label></div></div><label class="field-label mt-5">Section data (JSON)</label><textarea class="field h-auto font-mono text-sm py-3" rows="12" name="section_data[<?= $section['id'] ?>]" spellcheck="false"><?= e(json_encode(json_decode($section['data']?:'{}',true),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)) ?></textarea></section><?php endforeach; ?><button class="btn btn-primary">Save page</button></form>
